    lead:"本报讯 昨日凌晨，临渡城西厂食堂挂钟停摆，两班人员交接时各蒸了一笼馒头。食堂清点订餐单后多出100个馒头，上午在原窗口按平日价零售。",
    body:[
      "记者查看食堂交班记录，凌晨的挂钟停在3时，先后当班的师傅都把当天的首笼记在各自的交班单上，填的时间都是3时。夜班工人在6时下工，第二笼馒头刚出锅。到7时30分，各班组订餐数已全部结清，仓管将多出的100个另装入两个筐，挪到窗口出售。",
      "“我跨进门，他刚把锅盖盖上。我以为这是给夜班的，顺手又上了一屉。等两笼一起冒汽，我们才发现都蒸的是早饭。”接班厨师胡建民说。他开窗时，一名工人带着饭盒来，里面还有前晚剩的凉馒头。“两笼都还热。师傅见我带了凉的，先给我换了个热馒头。”夜班车工王志国说。",
      "厂办让食堂按原价处理余量，窗口另记零售账，免得与班组订餐混算。电工更换电池后，食堂挂钟已恢复走动。食堂负责人表示，从昨晚开始，交班单在时间之外加填已上锅的笼数，并由接班人员核对签字。昨日上午增加的馒头已处理完毕，今天供应照常。"
    ],
    short:"本报讯 昨晨城西厂食堂的挂钟停在3时，交班前后的师傅各蒸了一笼馒头。食堂核完订餐单，多出100个，上午在原窗口按平日价出售，已处理完毕。电工已换电池，食堂从昨晚起在交班单上加写上锅笼数。"
