    title:"纸坊巷废井捞出九棵白菜",
    lead:"本报讯 昨日上午，临渡纸坊巷清洁工打开一口停用浅井清理杂物，捞出九棵白菜。居民称前夜听到井盖响动，疑有人向井里扔菜，街道已更换锁扣。",
    body:[
      "记者在清理现场看到，工人用长竹夹夹出菜叶、整棵白菜和一团湿麻绳。几棵菜外叶已经发蔫，也有两棵菜心仍青。楼上有人坚持听见十声，等在井口的居民数到九棵就不肯走，直到工人打开手电筒查过井底，确认暂未再找到整棵白菜。",
      "“我听见井口响了十下，响完还在窗边等了会儿，以为它还要响。”住在二楼的退休木工朱建国说。楼下住户称自己只听见三声，此后一直下雨，分不清是棚顶还是井盖的响声。“我的车掉过一袋菜，在哪条巷子散的，说不准。”隔街菜贩李明华说。他昨日推来一只坏车轮。记者核对修车收据，只记载换轮轴，无法确认当时车上载了什么。",
      "街道下午更换了井盖锁扣，也查看了井沿，未发现近期搬动物品留下的印记。清出的白菜与麻绳暂存清洁站。隔街菜贩来辨认过，但他说自家用的捆菜绳要细得多。截至记者发稿，街道尚未查清白菜何时入井。"
    ],
    short:"本报讯 昨日上午，纸坊巷清洁工在一口停用浅井内捞出九棵白菜和一团湿麻绳。居民对前夜听到的响声次数说法不一，隔街有菜贩称车上掉过菜，尚无凭据能对上。截至发稿，街道已更换井盖锁扣，暂未查清白菜入井时间。",
