      "“交班时还得清点工件。上一班报完数，我们还要查哪些半成品需返工。”车工陈小平说。厂劳资室介绍，早到的人过去主要在院内等开工，今年夏天改为在这个时段清点工件，计时表却沿用旧格式。记者对照过新交接规定和财务表，也发现工时栏没有作相应调整。",
