    lead:"本报讯 昨日，临渡老站口的公用电话亭拆除，原号码停用。记者实地走访附近三处公话，离原址最近的报亭可接电话，营业至19时。",
    body:[
      "记者从公话亭原址分别往报亭、粮店和河堤方向走访。报亭可拨打电话，也愿意替街坊代接来电，营业至19时。粮店的公话可向外拨号，柜台忙时不代接。河堤下的小卖部步行约12分钟，营业到21时。记者试拨公话亭原号码，未能接通。",
      "“我还在凳子上等，以为家里人忘了。他们每周都往这儿打电话。”附近钟表店学徒吴鑫说。得知电话拆除后，他到报亭重新约好下一次通话。附近几家旅馆已经把原来贴在柜台的公话提示换掉。",
      "“只要事先跟我们打声招呼，叫得着的人，我们可以帮忙喊一声。我七点收摊，再晚这电话就没人接了。”报亭经营者刘福生说。街道表示，原公话亭旁的长凳将继续留作候车用。仍与外地亲友约定用原号码通话的居民，请及时改约电话号码和时段。"
    ],
    short:"本报讯 老站口公话亭昨日拆除，原号码停用。记者走访附近三处公话，紧邻报亭可代接至19时，粮店忙时只供拨出，河堤小卖部距旧亭步行约12分钟，可接听到21时。约好由外地亲友打来的人可及时改约号码和时段。"
