    title:"纸坊巷修伞摊备三把旧伞，路人可免费借用",
    lead:"本报讯 前日，临渡纸坊巷修伞摊将三把修好的旧伞放在摊前供路人免费借用。摊主说，三把伞均经原主同意，伞柄上缠有胶布，借还只登记日期。",
    body:[
      "记者在巷口看到，修伞摊借用了隔壁鞋摊半边桌面。待修和等取的伞仍放在桌上，可出借的旧伞放在桌下。借用人可自行查看有没有空伞，找摊主记下出借日期即可，归还时再填一次。到昨日下午，已有人借走半天就送回来，又替仍在店里搬货的人借走另一把。",
      "“几把伞都问过原主人。有的人已经买了新伞，愿意把修好的留在摊上借。”修伞摊主陈国栋说。前日借出的第一把伞已于昨日交回，归还人还在登记簿上留了两枚衣扣，摊主称当时并未约定收任何东西。",
      "“下周再把桌板往外伸一点，避雨的人也能站得下。”隔壁鞋摊摊主吴晓梅说。修伞摊通常在白天出摊，借伞不收押金。拿了伞的居民可择日归还；若摊主暂时不在，可请隔壁鞋摊代收。摊主表示，坏伞可先送回原摊检查，借伞人不必自行找人维修。"
    ],
    short:"本报讯 纸坊巷修伞摊前日起把三把修好的旧伞放在摊前，征得原主同意后供路人免费借。能借的伞柄统一缠有胶布，可择日归还，不收押金。昨日下午有借伞人还伞后，又替在店里搬货的人借走一把，隔壁鞋摊可帮忙代收。"
