    lead:"本报讯 昨日下午，临渡文化馆举行卡拉OK比赛，原本到场搬音箱的东门鱼摊摊主罗建华临时替补出场，以0.5分优势夺冠，奖品为一台双卡录音机。",
    body:[
      "昨日下午开赛前，一名报名选手来电称没赶上车。主持人向现场观众征求替补时，帮亲戚搬音箱的罗建华报了歌名。记者在后台看到，他的名字先签在搬运簿上，参赛名单最后一栏是临时添的。“我本来是去搬音箱的。人家问谁愿意上，我先问能不能替我把剩下那台搬进去。”34岁的鱼摊摊主罗建华说。",
      "记者核对三名评委的评分单，罗建华总分比亚军高0.5分，有评委给了较高的音准分，也有人在表上写下“尾音太快”。颁奖后有街坊到鱼摊问他平时在哪儿练歌，同排摊主说，他多数时候等顾客找零钱才哼几句。",
      "“算出他多半分，台下还喊再唱一首。我怕自己加错，把三张纸拿回来重新算了一遍，还是他高。”比赛计分员何小敏说。罗建华已领走双卡录音机，比赛录音留在文化馆。馆方核对参赛名单与总分后，决定今天上午在门口公布正式名次。"
    ],
    short:"本报讯 昨日下午，东门鱼贩罗建华帮人搬音箱时遇到临渡文化馆卡拉OK赛有人缺席，临时替补登台，以0.5分优势夺冠。记者在后台查到，他的名字原先签在搬运簿上。罗建华已领走双卡录音机，文化馆将张贴获奖名单及总分。"
