      "“走到厂门口，先听见有人在喊各自被欠了多少。我们叫厂里把花名册搬出来，一页页对，免得漏临时工。”现场劳动监察员吴同志说。劳动部门要求厂方下周提交付款安排和核账结果，首笔发放时将核对领取人及实际金额。"
