    source:"https://cn.govopendata.com/renminribao/2003/07/04/2/",
    title:"淮河洪峰通过王家坝，临渡启运860床赈灾被褥",
    lead:"本报讯 昨晚，临渡民政部门将首批860床被褥装车，发往安徽淮河灾区。王家坝闸7月3日开启分洪，国家防总消息显示，洪峰已安全通过王家坝河段。",
    body:[
      "7月3日凌晨，淮河蒙洼蓄洪区启用。据7月4日《人民日报》报道，蒙洼蓄洪区内15万居民已转至安全庄台和大堤。国家防总公布的数字显示，截至昨日19时，王家坝水位回落到28.96米。",
      "记者昨日下午到临渡救灾物资库时，捐来的被褥和库存棉被已分垛核点。",
      "“有个阿姨把自家新被子放下就走了。我追到门口，才问清她是把自己原来备着过冬的一床也一起送了。”负责清点的志愿者杨娟说。被褥清点完由民政人员装车，车上另配有帆布遮雨，装车清单随车交给接收方，货物到达后将由两地民政部门核对签收。",
      "“那边已经把接货地点报给我了。到了先找值班人，不能把东西堆在路边就算交了。”出车驾驶员马建民说。临渡民政局昨晚确认首批车辆已出城，下一批以桶装饮用水为主，正在按灾区接收单位反馈核定数量。"
    ],
    short:"本报讯 临渡民政部门昨夜将首批860床被褥发往安徽淮河灾区，下一批物资以饮用水为主。王家坝闸7月3日开闸分洪，洪峰已安全通过该河段。截至昨日19时，王家坝水位已回落至28.96米。"
