    short:"本报讯 临渡青石街一间商铺昨日上午安装空调时，外机从二楼坠落，砸伤3名路人。急救人员将伤者分送两家医院。街道已接收安装单，通知暂停作业。昨晚1名伤者仍住院治疗，另2人已回家休养。路段现已恢复通行。"
