    title:"区办购礼盒花费7880元，财务列入培训材料",
    lead:"本报讯 昨日，记者核对临渡南池区商贸办一笔账款，发现7880元礼盒发票列入培训材料支出。区财政检查组已调走相关账册，商贸办称正在核实领用去向。",
    body:[
      "记者先在该办年度公开账目里抄下日期和金额，再联系出具发票的百货柜台。柜台账档记载当日发出40盒茶礼，发票号与培训支出附件一致。记者另查培训签到页，其中只注明讲课、印材料，未列礼盒。具体去向与用途尚未查明。记者又核对发货日期与培训签到日期，发货在培训结束后，附件未注明如何补发给学员。",
      "“那天他们提走四十盒茶礼，我一盒盒点过。取货人说发票抬头写商贸办，我就照这几个字开的。”柜台发货员陈建华说。商贸办随后提供领用簿，上面未写培训场次及领用人。",
      "“我手里只有去取货的人签的条子，谁拿回去我得再去找人对。”商贸办经办人孙同志说。",
      "检查组已将发票、百货出货单与培训资料分开保存，并要求该办补齐签领依据。是否符合财务列支规定，待核对领用记录后处理。"
    ],
    short:"本报讯 临渡南池区商贸办一笔7880元礼盒支出列作培训材料费。记者对照百货出货单与培训凭证，发票号码一致，所领用途未列明。区财政检查组已调取账册，商贸办称还在核对签领记录和礼盒的去向。"
