    reporting:"调查",
    salesFactor:77, newsValue:90,
    title:"车站执法点扣住9张车票，旅客未领凭条",
    lead:"本报讯 昨日，临渡南站执法点拦查代售车票时暂扣9张票，票主未当场领到凭条。市运输执法部门已封存当班记录，逐张查明票源和归属。",
    body:[
      "记者在南站值班窗看到，暂扣物清单写了日期、票号和车次，未填经手人。三名旅客拿来购票回执，号码与清单中的票能对上。站方售票窗口核对票根后称，这几张票均来自本窗口，但转手经过还需向持票人询问。",
      "“我拿票是替家里人排队，他去搬箱子了。票被拿走以后我跑去问要张条，回来时那班车已经开了。”返乡旅客陈志国说。陈志国出示的车票收据上有购票时刻。记者抄下号码交给值班窗，站方查得票已过了原列车的检票时间。执法点未填写当事人所述的购票经过。",
      "“当时只抄了票号，以为查清就能原样给回去。人跟票没一一对上，补单得逐个确认。”执法点当班负责人黄同志说。市运输执法部门已将确认票主的四张票用于退票或改签，其余票据继续核查，执法人员处理过程将一道复核。"
    ],
    short:"本报讯 临渡南站执法点昨日暂扣9张车票，部分旅客称未获凭条。记者核对购票回执和站内清单，有三名旅客的号码能够对应。市运输执法部门已收走当班记录，确认票主的四张票已用于退票或改签，其余票的来源仍在核查。"
