      "“上一回他们进了隔壁，我还拿着证在门口等。等他们走了，说名单上压根没有我。”东关路一家网吧的经营者刘志国说。",
      "文化局找出稽查人员当时用的旧底表。它抄自新许可证入册前的一次汇总。首轮检查仍在记录，文化局昨日通知未检查的网吧补查，处理结果将与先查的各家同时公布。文化局还要核对已经搬走的店。此前有些经营地址也未从旧表上删掉。",
      "“用错了册，这就是漏查。上回没去的，这回得把门一家一家走到。”市文化局市场管理科负责人赵同志说。"
