      "“照片摞起来一样大。自己照的不能收，对街再照一张就收。我到底换证还是给他找生意？”修锁摊主赵建华说。他把两张照片摊在窗口下的小台上。",
      "市容队昨日换了告示，把照相店的名称从提示上去掉。两位摊主原先拍的照片经现场比对，尺寸符合要求，窗口重新收了材料。其余因此退回的申请，队里还要逐件复核。仍有人排队等窗口给答复。",
      "“先前是有人把照片带大了，让他去对街裁。店名后来贴出去，是我们窗口写的。今后照片合尺寸就收。”市容队办证组负责人郭同志说。"
