    short:"本报讯 临渡城西市容队换证窗口原先在提示单上指定一家照相店。记者核对换证材料要求，两位摊主的原照片符合尺寸。窗口昨日撤下店名，并重新接收两位摊主的原照片。其余退件待复核。"
