      "将近中午，附近装卸队的老秦拎来几只右手套。他干活时习惯左手抓带子，破的全是左手。店主在柜台上让他伸手试过，收下两只还完好的右手作交换。原先那筐左手终于少了两只。有两名顾客见了，又回家拿以前落单的手套。大小不对的，她仍请人带回。",
      "“我头一回见有人带着满包右手来买左手。以后先问他用哪只手干活。”店主刘志刚说。"
