    short:"本报讯 临渡石板巷一家日杂铺昨日将帆布手套按左右手拆开卖。午前14只右手套被买光，左手套仍剩下一筐。附近一名惯用左手的装卸工随后带来多出的右手套，换走两只左手套，小铺又有右手套可配。"
