    short:"本报讯 临渡一家证券营业部开盘前，退休会计李德明带着算盘在阅报桌上算账。几名股民以为他在算股票，走近才发现是帮门口茶摊核茶钱。茶摊老板领走账，老人又给邻座股民指了指交割单上的金额。"
