      "“那时候老师傅把银幕撑在场院上，我站后头也看过这一段。后来进厂了，一早一晚挤不出时间重看。”附近鞋厂工人王小红说。那天她从食堂出来，还带着饭盒，进门就认出了画面里的人。",
      "片子播完，几名老观众在门口说起电影队原先去过的村子。厂里还没打铃，他们聊了几句才走。录像厅打算继续开午场，旧电影片名由观众先提。有人临走又报了一个片名。",
      "“那时在哪个村放，现在还真有人记得。只要午休来得及，我就挑一段给他们放。”录像厅经营者吴建国说。"
