      "“我替厂里看了两轮，凳子都坐熟了。我一跑到边上，才想起来还不知道接球那个人姓啥。”临时队前锋陈小峰说。他上半场传丢过一次，下半场从左边把球送到了门前。",
      "桥北队先入一球，临时队下半场把比分扳平。终场以后，几名队员在边线上互报名字，说明下回比赛会穿什么衣服。联赛方在记分板上单独写了这场的结果。几个替补说，下次也想报名。",
