    short:"本报讯 临渡市民球场业余足球联赛昨晚加赛，四支队伍的12名替补临时组队，与轮空的桥北队踢成1比1。加赛比分单独记在记分板上，联赛积分照常计算。球场拟视下轮轮空队与替补球员的意愿再作安排。"
