    short:"本报讯 临渡工人文化宫昨日举行街坊象棋赛，最后一局增设墙挂大棋盘。工作人员按裁判记录复现落子，后排观众回到座位也能看清。赛后两处盘面经核对相符，文化宫拟在下一场公开赛继续使用。"
