    short:"本报讯 临渡河西工人俱乐部昨日试亮修好的春节庙会旧走马灯，原来残缺的六匹纸马已补齐并重新转动。修复者参考了庙会旧照和残存纸马。俱乐部将把走马灯和旧照一起留在后屋，平日供街坊参观。"
