旧云肩补的新花，花心用的是当年一粒扣|一位老演员把珍藏的戏衣借给学生，缺角的云肩要补一朵绒花。老师从旧扣盒找回同批的一粒金扣，恰好用来做花心。|扣面边缘有一道很细的铜线，绒线绕过以后刚好盖住缺口。学生把补好的云肩放回旧照片旁，花心大小同原先那朵几乎一样。
